private void initResources(ResourceBundle resourceBundle, Map<String,String> resources) {
  Enumeration<String> colorKeys = resourceBundle.getKeys();
  while (colorKeys.hasMoreElements()) {
    try {
      String key = colorKeys.nextElement();
      String value = resourceBundle.getString(key);
      resources.put(key, value);
    } catch (MissingResourceException | ClassCastException | NullPointerException | UnsupportedOperationException | IllegalArgumentException e) {
      // 根据业务需求处理异常，例如记录日志或忽略
      System.err.println("Warning: Failed to process resource key: " + e.getMessage());
    }
  }
}
